CREATE EXTENSION IF NOT EXISTS "pgcrypto";
DROP TABLE IF EXISTS push_subscriptions, password_resets, refresh_tokens, notifications, event_targets, abnt_references, flashcards, direct_messages, social_poll_votes, social_comments, social_likes, social_posts, follows, study_posts, study_rooms, chat_messages, material_progress, material_versions, submissions, assignments, forum_replies, forum_questions, notes, materials, notices, events, subjects, users CASCADE;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('PROFESSOR','ALUNO')), avatar_path TEXT, course VARCHAR(120), semester VARCHAR(30), ra VARCHAR(40), institution VARCHAR(120), bio VARCHAR(300), username VARCHAR(20) UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL, code VARCHAR(50), professor_id UUID REFERENCES users(id) ON DELETE SET NULL, semester VARCHAR(30) DEFAULT '26.2', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE materials (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id) ON DELETE SET NULL, title VARCHAR(200) NOT NULL, description TEXT, type VARCHAR(30) NOT NULL CHECK (type IN ('VIDEO','PDF','LINK','EXERCICIO','PROVA')), url TEXT, file_path TEXT, tags TEXT[] DEFAULT '{}', version INTEGER NOT NULL DEFAULT 1, due_date TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE material_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), material_id UUID NOT NULL REFERENCES materials(id) ON DELETE CASCADE, version INTEGER NOT NULL, file_path TEXT, file_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(material_id, version));
CREATE TABLE material_progress (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, material_id UUID NOT NULL REFERENCES materials(id) ON DELETE CASCADE, completed BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id, material_id));
CREATE TABLE notes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, content TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id, subject_id));
CREATE TABLE notices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID REFERENCES subjects(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id) ON DELETE SET NULL, title VARCHAR(200) NOT NULL, content TEXT NOT NULL, pinned BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE assignments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, description TEXT, due_date TIMESTAMPTZ NOT NULL, max_score NUMERIC(5,2) DEFAULT 10, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID REFERENCES subjects(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id) ON DELETE SET NULL, title VARCHAR(200) NOT NULL, description TEXT, event_date TIMESTAMPTZ NOT NULL, type VARCHAR(30) DEFAULT 'OUTRO', color VARCHAR(20), visibility VARCHAR(20) NOT NULL DEFAULT 'ALL' CHECK (visibility IN ('ALL','SELECTED','PRIVATE')), reminder_sent_at TIMESTAMPTZ, source_assignment_id UUID REFERENCES assignments(id) ON DELETE CASCADE, source_material_id UUID REFERENCES materials(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE event_targets (event_id UUID NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(event_id, user_id));
CREATE TABLE submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id UUID NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, file_path TEXT, file_name TEXT, file_size BIGINT, score NUMERIC(5,2), feedback TEXT, submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(assignment_id, student_id));
CREATE TABLE forum_questions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), material_id UUID NOT NULL REFERENCES materials(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id) ON DELETE SET NULL, question TEXT NOT NULL, answered BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE forum_replies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), question_id UUID NOT NULL REFERENCES forum_questions(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id) ON DELETE SET NULL, content TEXT NOT NULL, official BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE study_rooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, description TEXT, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE study_posts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES study_rooms(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id) ON DELETE SET NULL, content TEXT NOT NULL, link TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE chat_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, type VARCHAR(40) DEFAULT 'INFO', read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE abnt_references (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject_id UUID REFERENCES subjects(id) ON DELETE SET NULL, type VARCHAR(30) NOT NULL, data JSONB NOT NULL DEFAULT '{}', formatted TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE push_subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, endpoint TEXT UNIQUE NOT NULL, subscription JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE password_resets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE follows (follower_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, following_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(follower_id, following_id), CHECK (follower_id <> following_id));
CREATE TABLE social_posts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, poll_options TEXT[], repost_material_id UUID REFERENCES materials(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE social_likes (post_id UUID NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(post_id, user_id));
CREATE TABLE social_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), post_id UUID NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE, author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, parent_id UUID REFERENCES social_comments(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE social_poll_votes (post_id UUID NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, option_index INTEGER NOT NULL CHECK (option_index >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(post_id, user_id));
CREATE TABLE direct_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, type VARCHAR(10) NOT NULL DEFAULT 'TEXT' CHECK (type IN ('TEXT','IMAGE','AUDIO')), content TEXT NOT NULL DEFAULT '', file_path TEXT, file_name TEXT, file_size BIGINT, duration_ms INTEGER, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE flashcards (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject_id UUID REFERENCES subjects(id) ON DELETE SET NULL, material_id UUID REFERENCES materials(id) ON DELETE SET NULL, front TEXT NOT NULL, back TEXT NOT NULL, box INTEGER NOT NULL DEFAULT 1 CHECK (box BETWEEN 1 AND 5), due_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), last_reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_materials_subject ON materials(subject_id); CREATE INDEX idx_events_date ON events(event_date); CREATE INDEX idx_event_targets_user ON event_targets(user_id); CREATE INDEX idx_assignments_due ON assignments(due_date); CREATE INDEX idx_notifications_user ON notifications(user_id, created_at DESC); CREATE INDEX idx_abnt_refs_user ON abnt_references(user_id); CREATE INDEX idx_chat_subject ON chat_messages(subject_id, created_at DESC); CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id); CREATE INDEX idx_social_posts_author ON social_posts(author_id, created_at DESC); CREATE INDEX idx_follows_following ON follows(following_id); CREATE INDEX idx_social_poll_votes_post ON social_poll_votes(post_id); CREATE INDEX idx_dm_sender ON direct_messages(sender_id, created_at DESC); CREATE INDEX idx_dm_recipient ON direct_messages(recipient_id, read_at, created_at DESC); CREATE INDEX idx_flashcards_user_due ON flashcards(user_id, due_at); CREATE INDEX idx_social_comments_parent ON social_comments(parent_id);
